{"code": "import re
import json

titles = {
    "Kh8tGD5liwo": "零成本本地 AI Agent 部署简报：Hermes 与 Qwen3.6 的深度整合方案",
    "NbldZVdusKo": "Hermes Agent 与 OpenClaw 深度对比简报：下一代自我进化智能体分析",
    "krEDel3aGGw": "GPT-5.5 Instant 模型发布与性能分析简报"
}

def make_slug(title):
    slug = []
    for ch in title:
        cp = ord(ch)
        # Keep: Chinese characters, English letters, digits
        if (0x4e00 <= cp <= 0x9fff) or ('a' <= ch <= 'z') or ('A' <= ch <= 'Z') or ('0' <= ch <= '9'):
            slug.append(ch)
        else:
            # Replace everything else with '-'
            if slug and slug[-1] != '-':
                slug.append('-')
    # Collapse consecutive '-' and trim
    result = re.sub(r'-+', '-', ''.join(slug)).strip('-')
    # Take first 40 chars
    result = result[:40]
    return result

for video_id, title in titles.items():
    slug = make_slug(title)
    print(f"{video_id}: '{title}'")
    print(f"  -> slug: '{slug}' (len={len(slug)})")
    print()
"}

